    "package.json": "{\n  \"name\": \"noter-starter-template\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"packageManager\": \"pnpm@9.15.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"npm-run-all --parallel dev:frontend dev:backend\",\n    \"dev:frontend\": \"vite\",\n    \"dev:backend\": \"convex dev\",\n    \"build\": \"vite build\",\n    \"build:frontend\": \"vite build\",\n    \"preview\": \"vite preview\",\n    \"lint\": \"tsc --noEmit\",\n    \"test\": \"vitest run --passWithNoTests\",\n    \"prepare\": \"husky\",\n    \"template:export\": \"node scripts/export-template-manifest.mjs\"\n  },\n  \"dependencies\": {\n    \"@radix-ui/react-checkbox\": \"^1.3.3\",\n    \"@radix-ui/react-slot\": \"^1.2.3\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"convex\": \"1.27.5\",\n    \"lucide-react\": \"^0.525.0\",\n    \"npm-run-all\": \"^4.1.5\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tailwind-merge\": \"^2.5.2\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^18.3.3\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"@vitejs/plugin-react\": \"^5.0.0\",\n    \"autoprefixer\": \"^10.4.20\",\n    \"husky\": \"^9.1.7\",\n    \"postcss\": \"^8.4.49\",\n    \"tailwindcss\": \"^3.4.14\",\n    \"tailwindcss-animate\": \"^1.0.7\",\n    \"typescript\": \"5.9.2\",\n    \"vite\": \"^6.0.0\",\n    \"vitest\": \"^1.0.0\"\n  }\n}\n",
